import unittest
from workload import trial, equivalent


class Part1(unittest.TestCase):
    def test_1_anisotropic_bowl(self):
        args = [[1, 2], [[1, 0], [0, 2]], [0, 0]]
        expected = {'gradient': [1, 4], 'loss': 4.5}
        actual = trial('quadratic_state.quadratic_state', args)
        self.assertTrue(equivalent(actual, expected), (actual, expected))

    def test_2_linear_term(self):
        args = [[0], [[2]], [3]]
        expected = {'gradient': [3], 'loss': 0.0}
        actual = trial('quadratic_state.quadratic_state', args)
        self.assertTrue(equivalent(actual, expected), (actual, expected))


